import json,pathlib,hashlib,struct,zlib
m=json.load(open('manifest.json'))['items']; s=json.load(open('submission.json'))['items']; r=json.load(open('media-results.json'))['runs']; h=json.load(open('run-inputs.json'))['runs']; assert all(len(x)==11 for x in (m,s,r,h)); out=[]
for i,(a,b,c,d) in enumerate(zip(m,s,r,h),1):
 assert a['request_id']==b['request_id']==c['request_id'] and b['run_id']==c['run_id']==d['run_id']; assert c['status']=='succeeded' and len(c['images'])==1
 params=d['arguments']['parameters']; assert params['positive_prompt']==pathlib.Path(a['parameter_files']['positive_prompt']).read_bytes().decode('utf-8')
 for k,v in a['request']['parameters'].items(): assert params[k]==v,(i,k)
 f=c['images'][0]['file_path']; data=pathlib.Path(f).read_bytes(); assert data[:8]==b'\x89PNG\r\n\x1a\n'; pos=8; chunks=[]; idat=b''; end=False
 while pos<len(data):
  n=struct.unpack('>I',data[pos:pos+4])[0]; kind=data[pos+4:pos+8]; payload=data[pos+8:pos+8+n]; crc=struct.unpack('>I',data[pos+8+n:pos+12+n])[0]; assert zlib.crc32(kind+payload)&0xffffffff==crc; pos+=12+n; chunks.append(kind)
  if kind==b'IHDR': w,hh,depth,color,comp,flt,inter=struct.unpack('>IIBBBBB',payload); assert (w,hh)==(512,512)
  if kind==b'IDAT': idat+=payload
  if kind==b'IEND': end=True; break
 assert end and pos==len(data); pixels=zlib.decompress(idat); assert len(pixels)>0
 if inter==0:
  channels={0:1,2:3,3:1,4:2,6:4}[color]; stride=(w*channels*depth+7)//8; assert len(pixels)==hh*(stride+1); assert all(pixels[j*(stride+1)]<=4 for j in range(hh))
 out.append({'index':i,'run_id':c['run_id'],'request_id':c['request_id'],'seed':params['seed'],'media_id':c['images'][0]['media_id'],'path':f,'size':[w,hh],'sha256':hashlib.sha256(data).hexdigest(),'prompt_matches':True})
pathlib.Path('verification.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n'); print(json.dumps(out,ensure_ascii=False,indent=2))
PY","timeoutMs":120000}

